class ReceiptApplyService:
    """Apply reviewed receipt mappings to aliases and pantry state."""

    @classmethod
    @transaction.atomic
    def apply_capture(
        cls,
        capture: GroceryReceiptCapture,
        *,
        user: Any,
        lines: list[ReceiptApplyLine],
    ) -> dict[str, Any]:
        applied_count = 0
        pantry_updates = 0
        for requested_line in lines:
            line = (
                capture.lines.select_for_update()
                .filter(id=requested_line.line_id)
                .first()
            )
            if (
                line is None
                or line.line_status == GroceryReceiptLine.LineStatus.DISCARDED
            ):
                continue
            product, confidence = cls._resolve_product(
                capture,
                line,
                requested_line,
                user=user,
            )
            line.matched_product_preference = product
            line.pantry_effect = bool(requested_line.pantry_effect)
            line.line_status = GroceryReceiptLine.LineStatus.RESOLVED
            line.save(
                update_fields=[
                    "matched_product_preference",
                    "pantry_effect",
                    "line_status",
                    "updated_at",
                ]
            )
            cls._learn_alias(line, product, user=user, confidence=confidence)
            applied_count += 1
            if requested_line.pantry_effect:
                cls._refresh_pantry(line, product, confidence=confidence)
                pantry_updates += 1
        return {"applied_count": applied_count, "pantry_updates": pantry_updates}

    @classmethod
    def _resolve_product(
        cls,
        capture: GroceryReceiptCapture,
        line: GroceryReceiptLine,
        requested_line: ReceiptApplyLine,
        *,
        user: Any,
    ) -> tuple[FamilyProductPreference, float]:
        candidate = None
        if requested_line.candidate_id:
            candidate = line.candidate_matches.filter(
                id=requested_line.candidate_id
            ).first()
            if candidate is None:
                raise ValueError(
                    "Receipt candidate does not belong to the requested line"
                )
            if candidate.product_preference_id and candidate.product_preference:
                if candidate.product_preference.family_id != capture.family_id:
                    raise ValueError(
                        "Candidate product preference does not belong to capture family"
                    )
                return candidate.product_preference, candidate.confidence_score
        if requested_line.product_preference_id:
            product = FamilyProductPreference.objects.get(
                id=requested_line.product_preference_id,
                family=capture.family,
                is_active=True,
            )
            return (
                product,
                candidate.confidence_score if candidate else line.confidence_score,
            )

        product_name = (
            requested_line.product_name
            or (candidate.display_name if candidate else "")
            or line.normalized_label
            or line.raw_label
        ).strip()
        existing = FamilyProductPreference.objects.filter(
            family=capture.family,
            product_name__iexact=product_name,
            is_active=True,
        ).first()
        if existing:
            product = existing
        else:
            product = FamilyProductPreference.objects.create(
                family=capture.family,
                product_name=product_name,
                created_by=user,
            )
        return (
            product,
            candidate.confidence_score if candidate else line.confidence_score,
        )

    @staticmethod
    def _learn_alias(
        line: GroceryReceiptLine,
        product: FamilyProductPreference,
        *,
        user: Any,
        confidence: float,
    ) -> GroceryProductAlias:
        normalized = normalize_product_label(line.raw_label)
        normalized_raw = normalize_receipt_label(line.raw_label)
        existing = GroceryProductAlias.objects.filter(
            family=line.receipt_capture.family,
            normalized_label=normalized,
        ).first()
        if existing and existing.product_preference_id == product.pk:
            update_fields = []
            if confidence > existing.confidence_score:
                existing.confidence_score = confidence
                update_fields.append("confidence_score")
            if normalized_raw and existing.normalized_raw_label != normalized_raw:
                existing.normalized_raw_label = normalized_raw
                update_fields.append("normalized_raw_label")
            if update_fields:
                update_fields.append("updated_at")
                existing.save(update_fields=update_fields)
            return existing
        alias, _created = GroceryProductAlias.objects.update_or_create(
            family=line.receipt_capture.family,
            normalized_label=normalized,
            defaults={
                "product_preference": product,
                "raw_label": line.raw_label,
                "normalized_raw_label": normalized_raw,
                "source": GroceryProductAlias.Source.RECEIPT,
                "confidence_score": confidence,
                "created_by": user,
            },
        )
        return alias

    @staticmethod
    def _refresh_pantry(
        line: GroceryReceiptLine,
        product: FamilyProductPreference,
        *,
        confidence: float,
    ) -> PantryItemState:
        now = timezone.now()
        capture = line.receipt_capture
        purchased_on = capture.purchased_on
        if purchased_on is None:
            user_timezone = getattr(
                getattr(capture.uploaded_by, "profile", None), "timezone", ""
            )
            purchased_on = timezone.localdate(
                now,
                timezone=resolve_pantry_timezone(user_timezone),
            )

        line_qty = _parse_line_quantity(line.quantity_text)

        existing = PantryItemState.objects.filter(
            family=capture.family,
            product_preference=product,
        ).first()

        if existing is None:
            new_qty = line_qty
        elif existing.marked_out_at is not None:
            # Re-stocking after marked out — quantity is what just arrived.
            new_qty = line_qty
        elif line.pk == existing.source_receipt_line_id:
            # Idempotent re-apply of the same line — keep existing tally.
            new_qty = existing.quantity
        else:
            new_qty = existing.quantity + line_qty

        pantry, _created = PantryItemState.objects.update_or_create(
            family=capture.family,
            product_preference=product,
            defaults={
                "base_confidence": max(0.0, min(1.0, float(confidence))),
                "quantity": new_qty,
                "purchased_on": purchased_on,
                "last_signal_at": now,
                "source_receipt_line": line,
                "marked_out_at": None,
                "marked_out_by": None,
            },
        )
        return pantry


_QTY_TOKEN_RE = re.compile(r"\d+")


def _parse_line_quantity(quantity_text: str | None) -> int:
    """Best-effort extract integer count from a receipt quantity string.

    Returns 1 when no count is present (weights like '1.5 lb' also default to 1
    since they aren't unit counts)."""
    if not quantity_text:
        return 1
    if "." in quantity_text:
        # Likely a weight or decimal measure — count as 1 unit.
        return 1
    match = _QTY_TOKEN_RE.search(quantity_text)
    if not match:
        return 1
    try:
        value = int(match.group(0))
    except ValueError:
        return 1
    return value if value > 0 else 1
